// Obtener lista de partners
const partners = [
  {
    id: 'partner_1',
    name: 'Tours Paradise',
    webhookUrl: 'http://host.docker.internal:3002/partners/webhook',
    hmacSecret: 'secret_123'
  }
];

const event = {
  eventType: 'payment.succeeded',
  timestamp: new Date().toISOString(),
  data: items[0].json
};

// Generar firma HMAC
const crypto = require('crypto');
const outputs = [];

for (const partner of partners) {
  const signature = crypto
    .createHmac('sha256', partner.hmacSecret)
    .update(JSON.stringify(event))
    .digest('hex');

  outputs.push({
    json: {
      partnerUrl: partner.webhookUrl,
      signature: signature,
      event: event
    }
  });
}

return outputs;
